python3 -c 'import os,json; n=b=nm=nb=0
for r,ds,fs in os.walk("."):
 for f in fs:
  p=os.path.join(r,f)
  if not os.path.islink(p):
   z=os.stat(p).st_size;n+=1;b+=z
   if p.startswith("./node_modules/"):nm+=1;nb+=z
print(json.dumps({"files":n,"bytes":b,"node_modules_files":nm,"node_modules_bytes":nb}))'

